'use strict';
// Shared portrait source: the 21 Oct portrait (Zoya's), 192 px with a clear background, shown 96 px wide beside every reply (bridge/love-spot-store.cjs).
const PORTRAIT_DATA_URL = 'data:image/webp;base64,';
// Clip a portrait as a profile avatar in both chat and the board.
const avatar = portrait => `data:image/svg+xml;base64,${btoa(`<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="192" height="192" viewBox="0 0 192 192"><defs><clipPath id="avatar"><circle cx="96" cy="96" r="96"/></clipPath></defs><g clip-path="url(#avatar)"><circle cx="96" cy="96" r="96" fill="#edf2ff"/><image width="192" height="192" xlink:href="${portrait}"/></g></svg>`)}`;
const FACE_DATA_URL = avatar(PORTRAIT_DATA_URL);
// Her other shots, made from that portrait on 28 Oct (Codex image generation, Masih: "maybe she sending a kiss or smiling
// or laughing"): pinned Matilda turns to them now and then (components/matilda-companion.tsx). 256 px, clear background.
const MATILDA_SHOTS = {
  smile: avatar('data:image/webp;base64,'),
  laugh: avatar('data:image/webp;base64,'),
  kiss: avatar('data:image/webp;base64,'),
};
const FACE_MIME_TYPE = 'image/svg+xml';
module.exports = { FACE_DATA_URL, FACE_MIME_TYPE, MATILDA_SHOTS, PORTRAIT_DATA_URL };
